/**
 *
 * Tooltip is a popup that displays information when hovering or focusing on an element.
 *
 * [Live Demo](https://www.primereact.org/tooltip/)
 *
 * @module TooltipRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseTooltipChangeEvent, UseTooltipExposes, UseTooltipProps, UseTooltipState } from '@primereact/types/headless/tooltip';
/**
 * Defines passthrough(pt) options type in Tooltip component.
 */
export type TooltipRootPassThroughType<E> = PassThroughType<TooltipRootInstance, E>;
/**
 * Defines passthrough(pt) options of Tooltip component.
 */
export interface TooltipRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TooltipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the trigger's DOM element.
     */
    trigger?: TooltipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the portal's DOM element.
     */
    portal?: TooltipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the positioner's DOM element.
     */
    positioner?: TooltipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the popup's DOM element.
     */
    popup?: TooltipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the arrow's DOM element.
     */
    arrow?: TooltipRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
export interface TooltipRootChangeEvent extends UseTooltipChangeEvent {
    /**
     * The open value of the tooltip.
     */
    value: boolean | undefined;
}
/**
 * Defines valid properties in Tooltip component.
 */
export interface TooltipRootProps extends BaseComponentProps<TooltipRootInstance, Omit<UseTooltipProps, 'tooltipManager' | 'onOpenChange'>, TooltipRootPassThrough> {
    /**
     * Callback fired when the tooltip's open state changes.
     * @param event The event that triggered the change.
     * @param event.value The new value of the tooltip's open state.
     * @returns void
     * @default undefined
     */
    onOpenChange?: (event: TooltipRootChangeEvent) => void;
}
/**
 * Defines valid state in Tooltip component.
 * @extends UseTooltipState
 */
export interface TooltipRootState extends UseTooltipState {
}
/**
 * Defines the methods and properties exposed by Tooltip component.
 * @extends UseTooltipExposes
 */
export interface TooltipRootExposes extends UseTooltipExposes {
}
/**
 * Instance of Tooltip component.
 */
export type TooltipRootInstance = ComponentInstance<TooltipRootProps, TooltipRootState, TooltipRootExposes>;
